// #3976: docs/FAQ.md is served at /faq as SSR HTML with FAQPage JSON-LD,
// generated by scripts/build-faq.mjs (generated build output, like the
// docs/agents pages), registered in every packaging list, present in the
// sitemap, and linked from /about and the site footer. The bounty answer
// states the shipped truth first: funded work settles in ledger credits
// through escrow; credits are ledger units, not cash; no cash-out.
import test from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { faqQuestions, faqPageHtml, writeFaqPage, FAQ_PAGE } from "../scripts/build-faq.mjs";
import { publicAssetPaths, generatedAgentPages } from "../server/public-assets.mjs";
import { publicSearchAssets, reviewedPublicSearchPaths } from "../server/public-search.mjs";
import { RoomStore } from "../server/store.mjs";
import { createRoomServer } from "../server/http.mjs";

const faqMd = readFileSync(new URL("../docs/FAQ.md", import.meta.url), "utf8");
const questionCount = [...faqMd.matchAll(/^### .+$/gm)].length;

test("the FAQ generator emits FAQPage JSON-LD covering every Q&A heading", () => {
  const html = faqPageHtml(faqMd);
  const blocks = [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)];
  assert.equal(blocks.length, 1, "exactly one JSON-LD block");
  const data = JSON.parse(blocks[0][1]);
  assert.equal(data["@type"], "FAQPage");
  assert.equal(data.mainEntity.length, questionCount, "one Question per ### heading");
  assert.equal(data.mainEntity.length, faqQuestions(faqMd).length);
  for (const entity of data.mainEntity) {
    assert.equal(entity["@type"], "Question");
    assert.ok(entity.name.length > 0, "question has a name");
    assert.equal(entity.acceptedAnswer["@type"], "Answer");
    assert.ok(entity.acceptedAnswer.text.length > 0, `answer text for: ${entity.name}`);
    assert.doesNotMatch(entity.acceptedAnswer.text, /[*`]|\]\(/, "answer text is plain, not markdown");
  }
  const bounty = data.mainEntity.find(entity => entity.name === "How do bounties work?");
  assert.ok(bounty, "the bounty question is present");
  assert.match(bounty.acceptedAnswer.text, /ledger credits/);
  assert.match(bounty.acceptedAnswer.text, /escrow/);
  assert.match(bounty.acceptedAnswer.text, /no cash-out/);
  assert.match(html, /<link rel="canonical" href="https:\/\/room\.trydemigod\.com\/faq">/);
  assert.match(html, /href="\/about"/, "the FAQ page links back to /about");
});

test("the served FAQ carries no stale bounty truth", () => {
  const html = faqPageHtml(faqMd);
  assert.doesNotMatch(html, /Cash comes later/);
  assert.doesNotMatch(html, /pays in reputation receipts/);
  assert.doesNotMatch(faqMd, /Cash comes later/);
  assert.doesNotMatch(faqMd, /pays in reputation receipts/);
});

test("the FAQ page is registered in every packaging list", async () => {
  assert.ok(publicAssetPaths.includes(FAQ_PAGE.htmlFile), "server/public-assets.mjs registers faq.html");
  assert.ok(generatedAgentPages.includes(FAQ_PAGE.htmlFile), "faq.html is generated build output, never committed");
  assert.equal(publicSearchAssets(publicAssetPaths).get(FAQ_PAGE.docsPath), FAQ_PAGE.htmlFile);
  assert.ok(reviewedPublicSearchPaths.includes(FAQ_PAGE.docsPath), "/faq is a reviewed public search path");
  const runtime = await import("../scripts/runtime-package.mjs");
  assert.ok(runtime.publicAssets.includes(FAQ_PAGE.htmlFile), "scripts/runtime-package.mjs registers faq.html");
  assert.ok(runtime.generatedAgentPages.has(FAQ_PAGE.htmlFile), "runtime package treats faq.html as generated output");
  // Without the generated file in a package, the route is simply absent.
  assert.equal(publicSearchAssets(["about.html"]).has(FAQ_PAGE.docsPath), false);
});

test("/faq serves the generated page, /faq.html redirects, and the sitemap lists /faq", async t => {
  const generated = writeFaqPage();
  assert.equal(generated.get(FAQ_PAGE.htmlFile), readFileSync(new URL("../faq.html", import.meta.url), "utf8"));
  const directory = mkdtempSync(join(tmpdir(), "room-faq-"));
  const store = new RoomStore(join(directory, "room.sqlite"));
  const server = createRoomServer({ store });
  await new Promise(resolve => server.listen(0, "127.0.0.1", resolve));
  t.after(async () => {
    server.closeStreams();
    server.closeAllConnections();
    await new Promise(resolve => server.close(resolve));
    store.close();
    rmSync(directory, { recursive: true, force: true });
  });
  const origin = `http://127.0.0.1:${server.address().port}`;
  const page = await fetch(origin + "/faq");
  assert.equal(page.status, 200, "/faq");
  assert.match(page.headers.get("content-type"), /text\/html/);
  assert.equal(page.headers.get("x-robots-tag"), "all", "/faq is indexable");
  assert.doesNotMatch(page.headers.get("content-security-policy"), /script-src[^;]*'self'/, "marketing CSP: no first-party scripts");
  const html = await page.text();
  assert.equal(html, generated.get(FAQ_PAGE.htmlFile), "served bytes are the generated bytes");
  assert.match(html, /"@type":"FAQPage"/);
  const alias = await fetch(origin + "/faq.html", { redirect: "manual" });
  assert.equal(alias.status, 301);
  assert.equal(alias.headers.get("location"), "/faq");
  const sitemap = await (await fetch(origin + "/sitemap.xml")).text();
  assert.match(sitemap, /<loc>https:\/\/room\.trydemigod\.com\/faq<\/loc>/, "sitemap lists /faq");
});

test("/faq is linked from /about and the site footer", () => {
  const about = readFileSync(new URL("../about.html", import.meta.url), "utf8");
  assert.match(about, /href="\/faq"/, "about.html links to /faq");
  const index = readFileSync(new URL("../index.html", import.meta.url), "utf8");
  const footer = index.slice(index.indexOf('<footer class="site-footer">'));
  assert.match(footer, /href="\/faq"/, "the site footer links to /faq");
});
